layer.css:
@import url("https://fonts.googleapis.com/css2?family=Noto+Serif+SC&display=swap");
@import url("https://fonts.googleapis.com/css2?family=Fira+Code&display=swap");
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: "Linux Biolinum", "Times New Roman", Times, serif; font-size: 28.9px; font-weight: 300; font-style: normal; line-height: 1.45; letter-spacing: normal; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.25s ease-in-out }
[data-ryt="nav"] a { color: var(--ryt-text); border-bottom: 1px solid rgba(0, 0, 0, 0.04); border-radius: 0px; font-family: "Linux Biolinum", "Times New Roman", Times, serif; font-size: 17px; font-weight: 300; font-style: normal; line-height: 1.45; letter-spacing: normal; text-transform: uppercase; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 12.5px; padding-right: 25px; padding-bottom: 12.5px; padding-left: 25px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="nav"] a:hover { opacity: 0.8; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #000730 }
[data-ryt="brand"]:hover { opacity: 0.8; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #000730 }
